#include <IQM/hdrvdp3/fftw_single_provider.h>
#include <fstream>
#include <iostream>
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("Usage DLL fresh-output");std::filesystem::path out=argv[2];if(std::filesystem::exists(out))throw std::runtime_error("Fresh output required");std::filesystem::create_directories(out);IQM::HDRVDP3::FFTWProviderSingle fft(argv[1]);using C=IQM::HDRVDP3::FFTWProviderSingle::Complex;auto make=fft.symbol<void*(*)(int,const int*,int,C*,const int*,int,int,C*,const int*,int,int,int,unsigned)>("fftwf_plan_many_dft");auto print=fft.symbol<char*(*)(void*)>("fftwf_sprint_plan");auto threads=fft.symbol<void(*)(int)>("fftwf_plan_with_nthreads");for(int t:{1})for(int batch:{7,8})for(bool interleaved:{false,true}){fft.forget();threads(t);int n=7680;IQM::HDRVDP3::FFTWProviderSingle::Memory a(fft,7680*batch*8),b(fft,7680*batch*8);auto plan=make(1,&n,batch,(C*)a.data,nullptr,interleaved?batch:1,interleaved?1:7680,(C*)b.data,nullptr,interleaved?batch:1,interleaved?1:7680,-1,82);if(!plan)throw std::runtime_error("Plan failed");std::string name=std::to_string(t)+"_"+std::to_string(batch)+"_"+std::to_string(interleaved);std::ofstream(out/(name+".txt"))<<print(plan);fft.destroy(plan);}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
